    const tasksMatch = path.match(/^\/api\/projects\/(\d+)\/tasks$/);
    const taskMatch = path.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
    if (req.method === 'GET' && tasksMatch) {
